package com.loopers.infrastructure.payment;
import com.fasterxml.jackson.databind.JsonNode;import com.loopers.domain.payment.PaymentGateway;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import org.springframework.web.util.UriComponentsBuilder;import java.util.*;
// Hides: simulator HTTP paths, nested response parsing, headers, and URI encoding.
@Component public class PgSimulatorPaymentGateway implements PaymentGateway{private final RestClient client=RestClient.create("http://localhost:8082");private Result result(JsonNode n){JsonNode d=n.path("data");return new Result(d.path("transactionKey").asText(),d.path("orderId").asText(),d.path("status").asText());}public Result create(String u,Request r){Result x=result(client.post().uri("/api/v1/payments").header("X-USER-ID",u).body(r).retrieve().body(JsonNode.class));return new Result(x.transactionKey(),r.orderId(),x.status());}public List<Result> findByOrderId(String u,String o){String uri=UriComponentsBuilder.fromPath("/api/v1/payments").queryParam("orderId",o).build().encode().toUriString();JsonNode d=client.get().uri(uri).header("X-USER-ID",u).retrieve().body(JsonNode.class).path("data");JsonNode rows=d.has("transactions")?d.path("transactions"):d;List<Result> out=new ArrayList<>();if(rows.isArray())rows.forEach(x->out.add(new Result(x.path("transactionKey").asText(),o,x.path("status").asText())));return out;}public Result findByTransactionKey(String u,String k){return result(client.get().uri("/api/v1/payments/{key}",k).header("X-USER-ID",u).retrieve().body(JsonNode.class));}}
